import{_ as o,C as s,o as e,c as n,a2 as l,b as i,w as a,a as d,E as g,a3 as E}from"./chunks/framework.BODD28Fk.js";const A="data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mNkYAAAAAYAAjCB0C8AAAAASUVORK5CYII=",b=JSON.parse('{"title":"정산 현황 관리","description":"","frontmatter":{},"headers":[],"relativePath":"ledger/status.md","filePath":"ledger/status.md","lastUpdated":1793458915000}'),C={name:"ledger/status.md"};function B(c,t,h,u,f,_){const r=s("Mermaid");return e(),n("div",null,[t[1]||(t[1]=l('<h1 id="정산-현황-관리" tabindex="-1">정산 현황 관리 <a class="header-anchor" href="#정산-현황-관리" aria-label="Permalink to &quot;정산 현황 관리&quot;">​</a></h1><p>프로젝트의 실시간 자금 현황, 당일 입출금 내역 및 예산 대비 집행 실적을 통합적으로 조회하고 마감 정산을 관리하는 화면입니다.</p><ul><li><strong>위치</strong>: <code>회계 자금 관리 &gt; 정산 현황 관리</code></li></ul><div class="tip custom-block"><p class="custom-block-title">📸 실제 화면 안내</p><p><img src="'+A+'" alt="정산 현황 관리 화면"><em>관리자 참고: 해당 화면의 실제 캡처 이미지를 <code>./images/status.png</code> 경로에 등록해 주세요.</em></p></div><h2 id="개요" tabindex="-1">개요 <a class="header-anchor" href="#개요" aria-label="Permalink to &quot;개요&quot;">​</a></h2><p>특정 <strong>기준일자</strong>를 중심으로 프로젝트의 현금성 자산 상태와 사업비 예산 집행 현황을 입체적으로 분석합니다. 은행 계좌별 잔액 현황, 일자별 상세 거래 내역, 그리고 사업비 예산 대비 실제 지출액을 대조하여 프로젝트의 재무 건전성을 실시간으로 파악하고 일일 마감 정산을 확정할 수 있습니다.</p>',6)),(e(),i(E,null,{default:a(()=>[g(r,{id:"mermaid-24",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20A%5B%221.%20%EA%B8%B0%EC%A4%80%EC%9D%BC%EC%9E%90%20%EC%84%A4%EC%A0%95%3Cbr%2F%3E(%EC%A1%B0%ED%9A%8C%20%EA%B8%B0%EC%A4%80%EC%9D%BC%20%EC%84%A0%ED%83%9D)%22%5D%20--%3E%20B%5B%222.%20%EA%B3%84%EC%A2%8C%EB%B3%84%20%EC%9E%94%EC%95%A1%20%EB%8C%80%EC%82%AC%3Cbr%2F%3E(%EC%A0%84%EC%9D%BC%EC%9E%94%EA%B3%A0%20%C2%B1%20%EB%8B%B9%EC%9D%BC%EC%A6%9D%EA%B0%90%20%3D%20%EA%B8%88%EC%9D%BC%EC%9E%94%EA%B3%A0)%22%5D%0A%20%20%20%20B%20--%3E%20C%5B%223.%20%EB%8B%B9%EC%9D%BC%20%EC%9E%85%EC%B6%9C%EA%B8%88%20%EC%A0%90%EA%B2%80%3Cbr%2F%3E(%EA%B1%B4%EB%B3%84%20%EC%A0%81%EC%9A%94%C2%B7%EA%B3%84%EC%A0%95%EA%B3%BC%EB%AA%A9%C2%B7%EA%B1%B0%EB%9E%98%EC%B2%98)%22%5D%0A%20%20%20%20C%20--%3E%20D%5B%224.%20%EC%98%88%EC%82%B0%20%EC%A7%91%ED%96%89%20%EB%B6%84%EC%84%9D%3Cbr%2F%3E(%EA%B8%B0%EC%B4%88%2F%ED%98%84%ED%99%A9%20%EC%98%88%EC%82%B0%20%EB%8C%80%EB%B9%84%20%EC%A7%91%ED%96%89%EB%A5%A0)%22%5D%0A%20%20%20%20D%20--%3E%20E%5B%225.%20%EC%B5%9C%EC%A2%85%20%EC%A0%95%EC%82%B0%20%ED%99%95%EC%A0%95%3Cbr%2F%3E(%EC%8B%A4%EC%A0%9C%20%ED%86%B5%EC%9E%A5%20%EC%9E%94%EA%B3%A0%EC%99%80%20%EC%9E%A5%EB%B6%80%20%EB%A7%88%EA%B0%90)%22%5D%0A"})]),fallback:a(()=>[...t[0]||(t[0]=[d(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=l('<h2 id="주요-기능" tabindex="-1">주요 기능 <a class="header-anchor" href="#주요-기능" aria-label="Permalink to &quot;주요 기능&quot;">​</a></h2><ul><li><strong>기준일자별 시점 조회</strong>: 과거 또는 특정 날짜를 지정하여 해당 시점의 계좌 잔고와 입출금 내역을 그대로 재현</li><li><strong>계좌별 자금 흐름 동기화</strong>: 프로젝트가 보유한 모든 계좌의 전일 잔고, 당일 입출금 증감, 현재 잔고를 실시간 계산</li><li><strong>일일 입출금 상세 내역 대사</strong>: 기준일 당일 발생한 입금 및 출금 건별 적요, 회계 계정과목, 거래처 정보 조회</li><li><strong>사업비 예산 집행 분석</strong>: 승인된 기초 예산 및 변경된 현황 예산 대비 누적 집행액, 집행률, 잔여 가용 예산 모니터링</li><li><strong>원클릭 현황 예산 수정</strong>: 별도 설정 메뉴 이동 없이 화면 내에서 예산 항목 더블 클릭을 통한 인라인 즉시 수정</li><li><strong>캐시플로우(Cash Flow) 엑셀 출력</strong>: 경영진 보고 및 금융기관 제출용 표준 월별 자금 집행 서식 다운로드 지원</li><li><strong>최종 정산 확정(Check Balance)</strong>: 실제 은행 통장 잔액과 시스템 장부 금액의 일치를 검증하고 정산 마감 확정</li></ul><h2 id="화면-구성-및-실무-가이드" tabindex="-1">화면 구성 및 실무 가이드 <a class="header-anchor" href="#화면-구성-및-실무-가이드" aria-label="Permalink to &quot;화면 구성 및 실무 가이드&quot;">​</a></h2><h3 id="_1-기준일자-및-보고서-탭-선택" tabindex="-1">1. 기준일자 및 보고서 탭 선택 <a class="header-anchor" href="#_1-기준일자-및-보고서-탭-선택" aria-label="Permalink to &quot;1. 기준일자 및 보고서 탭 선택&quot;">​</a></h3><p>모든 데이터 집계의 기준이 되는 날짜를 지정하고 확인하고자 하는 세부 보고서 탭을 선택합니다.</p><ul><li><strong>기준일자</strong>: 오늘 날짜가 기본으로 설정되며, 날짜를 변경하면 해당 일자의 거래 상태로 모든 수치가 재계산됩니다.</li><li><strong>보고서 탭 전환</strong>: <ul><li><code>계좌별 자금현황</code>: 통장별 잔액 증감 현황</li><li><code>당일 입출금내역</code>: 기준일에 발생한 건별 입출금 명세</li><li><code>예산대비 집계</code>: 사업비 비목별 예산 집행 실적 및 잔여액</li></ul></li></ul><h3 id="_2-계좌별-자금현황-탭" tabindex="-1">2. 계좌별 자금현황 (탭) <a class="header-anchor" href="#_2-계좌별-자금현황-탭" aria-label="Permalink to &quot;2. 계좌별 자금현황 (탭)&quot;">​</a></h3><p>프로젝트가 보유한 보통예금 계좌들의 잔액 증감 현황을 한눈에 파악합니다.</p><table tabindex="0"><thead><tr><th style="text-align:left;">표시 항목</th><th style="text-align:left;">상세 설명 및 산출 공식</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>계좌명 (은행)</strong></td><td style="text-align:left;">프로젝트에 등록된 통장 별칭 및 금융기관 명칭입니다.</td></tr><tr><td style="text-align:left;"><strong>전일잔고</strong></td><td style="text-align:left;">기준일자 직전일까지의 누적 잔액입니다.</td></tr><tr><td style="text-align:left;"><strong>금일입금 (증가)</strong></td><td style="text-align:left;">기준일 당일 통장에 입금된 총금액입니다.</td></tr><tr><td style="text-align:left;"><strong>금일출금 (감소)</strong></td><td style="text-align:left;">기준일 당일 통장에서 출금된 총금액입니다.</td></tr><tr><td style="text-align:left;"><strong>금일잔고</strong></td><td style="text-align:left;"><code>전일잔고 + 금일입금 - 금일출금</code> 결과로 계산된 현재 시점의 실제 장부 잔고입니다.</td></tr></tbody></table><ul><li><strong>조회 필터 토글</strong>: <ul><li><code>잔고 존재 계좌만 보기</code>: 거래가 없거나 잔액이 0원인 비활성 계좌를 제외하고 실제 자금이 있는 계좌만 압축 조회</li><li><code>직불 용역비 계좌 포함</code>: 시공사 또는 용역사에 직불되는 특수 목적 계좌를 집계에 포함할지 여부 선택</li></ul></li></ul><h3 id="_3-당일-입출금내역-탭" tabindex="-1">3. 당일 입출금내역 (탭) <a class="header-anchor" href="#_3-당일-입출금내역-탭" aria-label="Permalink to &quot;3. 당일 입출금내역 (탭)&quot;">​</a></h3><p>기준일에 발생한 개별 거래의 상세 명세를 입금과 출금으로 구분하여 표시합니다.</p><ul><li><strong>표시 정보</strong>: 거래 발생 계좌명, 통장 적요(메모), 입금액/출금액, 매핑된 회계 계정과목 및 거래처 정보</li><li><strong>장부 대사 활용</strong>: 실제 은행 통장의 거래 내역서를 옆에 두고 건별로 적요와 금액이 빠짐없이 입력되었는지 대조할 때 활용합니다.</li></ul><h3 id="_4-예산대비-집계-탭" tabindex="-1">4. 예산대비 집계 (탭) <a class="header-anchor" href="#_4-예산대비-집계-탭" aria-label="Permalink to &quot;4. 예산대비 집계 (탭)&quot;">​</a></h3><p>프로젝트 초기 승인 예산과 실제 집행된 사업비 누계를 대조하여 예산 초과 여부를 감시합니다.</p><table tabindex="0"><thead><tr><th style="text-align:left;">집계 항목</th><th style="text-align:left;">상세 설명</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>예산 금액</strong></td><td style="text-align:left;"><strong>기초 예산</strong>(초기 수립 사업비) 또는 <strong>현황 예산</strong>(설계 변경 등으로 조정된 예산)을 라디오 버튼으로 전환 표시합니다.</td></tr><tr><td style="text-align:left;"><strong>전월 집행 누계</strong></td><td style="text-align:left;">기준일이 속한 당월 직전까지 집행된 누적 지출액입니다.</td></tr><tr><td style="text-align:left;"><strong>당월 집행 금액</strong></td><td style="text-align:left;">이번 달 1일부터 기준일까지 집행된 지출액입니다.</td></tr><tr><td style="text-align:left;"><strong>집행금액 합계</strong></td><td style="text-align:left;"><code>전월 집행 누계 + 당월 집행 금액</code>으로 산출된 현재까지의 총 지출 누계입니다.</td></tr><tr><td style="text-align:left;"><strong>가용 예산 합계</strong></td><td style="text-align:left;"><code>예산 금액 - 집행금액 합계</code>로 현재 추가 지출 가능한 잔여 예산입니다.</td></tr><tr><td style="text-align:left;"><strong>집행률 (%)</strong></td><td style="text-align:left;">예산 대비 누적 집행률을 백분율로 표시하며, 100% 초과 시 경고 색상으로 강조됩니다.</td></tr></tbody></table><ul><li><strong>캐시플로우(Cash Flow) 서식 다운로드</strong>: 우측 상단의 <strong>[캐시플로우 폼]</strong> 버튼을 누르면 연도별/월별 수입·지출 집행 내역이 정리된 표준 엑셀 보고서가 자동 생성됩니다.</li></ul><h3 id="_5-최종-정산-확정-check-balance" tabindex="-1">5. 최종 정산 확정 (Check Balance) <a class="header-anchor" href="#_5-최종-정산-확정-check-balance" aria-label="Permalink to &quot;5. 최종 정산 확정 (Check Balance)&quot;">​</a></h3><p>모든 입출금 입력과 계좌 대사가 완료된 후, 시스템 상의 장부 잔액을 공식 확정하는 기능입니다.</p><ul><li><strong>정산 상태 안내</strong>: 화면 하단에 마지막 거래일자와 현재 시스템 정산 마감일자를 비교하여 &quot;정산 필요&quot; 또는 &quot;정산 완료&quot; 상태를 표시합니다.</li><li><strong>정산 확정 버튼</strong>: 실제 은행 잔고와 장부 잔고가 100% 일치함을 확인한 후 [정산 확정]을 클릭하면 해당 일자까지의 마감 상태가 기록됩니다.</li></ul><h2 id="💡-실무-활용-팁" tabindex="-1">💡 실무 활용 팁 <a class="header-anchor" href="#💡-실무-활용-팁" aria-label="Permalink to &quot;💡 실무 활용 팁&quot;">​</a></h2><ul><li><strong>화면 내 현황 예산 즉시 수정</strong>: [예산대비 집계] 탭에서 &#39;현황 예산&#39; 라디오 버튼을 선택한 상태에서 <strong>예산 금액 셀을 마우스로 더블 클릭</strong>하면 입력창으로 전환되어 [프로젝트 설정 &gt; 예산 정보] 메뉴로 이동하지 않고도 즉시 변경 예산을 반영할 수 있습니다.</li><li><strong>일과 마감 시 일일 자금 대사(Reconciliation) 루틴</strong>: 매일 퇴근 전 [계좌별 자금현황]의 &#39;금일잔고 합계&#39;와 실제 은행 기업뱅킹 앱의 &#39;총 잔액&#39;을 대조하세요. 차액이 발생한다면 이체 수수료(500원 등) 누락이나 미등록 출금 건이 있는지 [거래 내역 관리]에서 확인해야 합니다.</li><li><strong>마감 데이터 무결성 보호</strong>: 최종 정산이 완료된 일자 이전의 거래 데이터는 임의 수정이 잠깁니다. 과거 정산 데이터를 수정해야 할 경우 상급 관리자 권한을 통해 정산 취소 또는 수정 승인을 거쳐야 합니다.</li></ul>',22))])}const p=o(C,[["render",B]]);export{b as __pageData,p as default};
